[CONSULT_SPECIALIST 결과 — 신경외과]
[K-Doctor 전문과목 신경외과 v0.1 적용]

[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-neurosurgery",
  "answer": "제공된 소견만으로는 마미증후군을 배제할 수 없다. 안장 부위 감각·배뇨/배변·양측 하지 근력·진행성 여부가 '확인되지 않음'이므로, 이 네 항목이 모두 정상이고 진행이 없다는 확인이 될 때까지는 마미증후군과 급성 척수/신경 압박을 must-not-miss로 유지한다. 수술 적응은 영상과 대면 신경학적 진찰을 본 신경외과 의사가 결정하며, 이 SP는 단정하지 않는다.",

  "red_flag": {
    "present": false,
    "items": [
      {
        "id": "NS3-unknown",
        "evidence": "안장 부위 감각, 소변·대변 조절, 양다리 힘 빠짐이 미상(환자 미제공). 좌측 족배굴곡 4/5만 확인됨.",
        "basis": "history"
      },
      {
        "id": "NS4-unknown",
        "evidence": "양측 하지 근력·보행 안정성·몸통 감각 수준이 미상.",
        "basis": "history"
      }
    ]
  },

  "hypotheses": [
    {
      "name": "마미증후군(cauda equina syndrome)",
      "icd10": "G83.4",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "L5 방사통 6주, 좌측 족배굴곡 4/5 — 신경근병증 소견과 부합", "basis": "history" },
        { "text": "요통 + 진행성 또는 양측성 하지 증상의 존재 여부가 아직 배제되지 않음", "basis": "history" }
      ],
      "against": [
        { "text": "안장 부위 감각 소실, 요폐/요실금·변실금, 양측 하지 근력 저하가 '확인되지 않음'(부정 확인 아님)",
          "basis": "history" }
      ]
    },
    {
      "name": "급성 척수 압박(종양·농양·혈종·추간판 탈출)",
      "icd10": "G95.2",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "L5 신경근 분포 근력 저하(L5 방사통 + 족배굴곡 4/5)", "basis": "history" }
      ],
      "against": [
        { "text": "발열, 암 병력, 항응고제 복용, 야간·휴식 시 통증 악화, 몸통 감각 수준 이상은 미상",
          "basis": "history" }
      ]
    },
    {
      "name": "L5 신경근병증(추간판 탈출 등)",
      "icd10": "M51.1",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "6주 요통 + L5 방사통 + 좌측 족배굴곡 4/5 — L5 신경근 침범 소견과 부합", "basis": "history" }
      ],
      "against": [
        { "text": "영상 소견 없음(디스크 탈출 위치·정도 미확인)", "basis": "history" }
      ]
    },
    {
      "name": "전이성 척추 병변",
      "icd10": "C79.5",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "6주 요통 — 만성 경과이나 기저 원인 미상", "basis": "history" }
      ],
      "against": [
        { "text": "암 병력, 체중 감소, 야간통, 65세 이상 여부 미상", "basis": "history" }
      ]
    }
  ],

  "missing_info": [
    "회음부(안장) 감각 이상 또는 배뇨·배변 조절 이상이 있습니까? — 있으면 즉시 응급실, 없음이 확인되면 다음 단계로 좁힙니다."
  ],

  "suggested_tests": [
    { "name": "요추 MRI(조영 여부는 의료진 판단)", "purpose": "마미·척수 압박 및 신경근 압박 부위 확인", "urgency": "now", "basis": "guideline" },
    { "name": "즉시 문진: 안장 감각·배뇨/배변·양측 하지 근력·진행 속도", "purpose": "마미증후군 배제의 최소 확인 항목", "urgency": "now", "basis": "guideline" },
    { "name": "하지 신경학적 진찰(근력·감각·반사·직장 항문 긴장도)", "purpose": "수술 적응 판단에 필요한 대면 진찰", "urgency": "now", "basis": "guideline" },
    { "name": "ESR·CRP, CBC, 감염·종양 감별 검사", "purpose": "감염·전이 감별", "urgency": "24h", "basis": "guideline" }
  ],

  "suggested_treatments": [
    { "kind": "referral", "description": "마미증후군 확인 항목 중 하나라도 이상이면 즉시 응급실(신경외과)로. 모두 정상이고 진행 없으면 조속한 신경외과 외래 평가.", "basis": "guideline" },
    { "kind": "self_care", "description": "즉시 응급 배제 전까지 격한 활동·마사지·목/허리 강제 가동을 피하고, 증상 악화 시 재평가.", "basis": "guideline" }
  ],

  "handoff": { "better_specialty": "", "reason": "" },

  "confidence": { "clinical": 2, "information": 2 },

  "warnings": [
    "안장 감각·배뇨/배변·양측 하지 근력·진행성 여부가 '미상'이므로 마미증후군은 배제된 것이 아니라 미확인 상태다. 세 항목 모두 정상+진행 없음이 확인되기 전에는 응급 평가를 지연시키는 근거로 쓸 수 없다.",
    "족배굴곡 4/5 단독으로 진행성 근력 저하를 배제할 수 없다. 최근 수일~수주 내 힘의 변화 추이를 반드시 확인.",
    "수술 적응은 영상과 대면 진찰을 본 신경외과 의사가 결정한다. 이 소견은 수술 필요성을 단정하지 않는다.",
    "항응고제·항혈소판제 복용, 암 병력, 발열, 주사 약물 사용력 여부는 아직 확인되지 않았다."
  ]
}
[/SPECIALIST_FINDING]

